// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint8 roleIdx, address account) public {
        vm.assume(account != address(0) && account != address(this) && account != address(c));
        bytes32 role;
        if (roleIdx % 3 == 0) role = c.TIMELOCK_ADMIN_ROLE();
        else if (roleIdx % 3 == 1) role = c.PROPOSER_ROLE();
        else role = c.EXECUTOR_ROLE();

        // deployer (test contract) holds TIMELOCK_ADMIN_ROLE and administers all roles
        c.grantRole(role, account);
        assertTrue(c.hasRole(role, account), "grant must confer the role");

        // the account renounces its own role
        vm.prank(account);
        c.renounceRole(role, account);

        // general rule: renouncing a role always removes membership
        assertTrue(!c.hasRole(role, account), "renounced role must be revoked");
    }
}
